import sys
from collections import defaultdict

def find_index_to_remove(n, b):
    if n == 2:
        return 1

    diff_count = defaultdict(int)
    max_diff_count = 0
    candidate_indices = []

    for i in range(1, n):
        diff = b[i] - b[i - 1]
        diff_count[diff] += 1
        if diff_count[diff] > max_diff_count:
            max_diff_count = diff_count[diff]
            candidate_indices = [i]
        elif diff_count[diff] == max_diff_count:
            candidate_indices.append(i)

    if max_diff_count * 2 >= n - 1:
        return 1

    for i in candidate_indices:
        diff = b[i] - b[i - 1]
        seen = set()
        valid = True
        for j in range(n):
            if j == i:
                continue
            if b[j] in seen:
                valid = False
                break
            seen.add(b[j])
            if j > 0 and b[j] - b[j - 1] != diff:
                valid = False
                break
        if valid:
            return i + 1

    return -1

